code='''def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    bg=max(set(x for r in g for x in r),key=lambda x:sum(r.count(x) for r in g))
    pts={(i,j) for i in range(h) for j in range(w) if g[i][j]!=bg}
    comps=[]
    while pts:
        stack=[pts.pop()]; comp=set(stack)
        while stack:
            i,j=stack.pop()
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(i+di,j+dj)
                if p in pts:
                    pts.remove(p); comp.add(p); stack.append(p)
        comps.append(comp)
    def box(c):
        return min(i for i,j in c),max(i for i,j in c),min(j for i,j in c),max(j for i,j in c)
    groups=[]
    for c in comps:
        b=box(c); joined=False
        for group in groups:
            a=box({p for cc in group for p in cc})
            if not (b[0]>a[1]+2 or a[0]>b[1]+2 or b[2]>a[3]+2 or a[2]>b[3]+2):
                group.append(c); joined=True; break
        if not joined: groups.append([c])
    for group in groups:
        pts2={p for c in group for p in c}; a,b,c,d=box(pts2)
        if any(box(comp)[1]>box(comp)[0] and box(comp)[3]>box(comp)[2] for comp in group):
            for i in range(max(0,a-1),min(h,b+2)):
                for j in (c-1,d+1):
                    if 0<=j<w and g[i][j]==bg:g[i][j]=2
            for j in range(max(0,c-1),min(w,d+2)):
                for i in (a-1,b+1):
                    if 0<=i<h and g[i][j]==bg:g[i][j]=2
    return g
'''
(progdir/(task+'.py')).write_text(code)
ns={};exec(code,ns)
for p in pairs: assert ns['transform'](p['input'])==p['output']
